SELECT  *  FROM t_apply

   deleted= 0 and #{now} < limit_start_time  and ( status = 3 or #{now} >= apply_end_time)

    and name like concat('%',#{name},'%')


    and  apply_archive_id in

      #{id}



    and id != #{selectId}


    and create_user = #{dataFilterUserId}


    and create_department_id in

      #{item}

select up.id , u.user_name as userName , u.real_name as realName , u.email , u.phone , u.id_card as idCard , u.work_no as workNo , u.job_title as jobTitle, up.create_time as createTime , u.department_id as departmentId
from t_user u LEFT JOIN t_user_apply up on u.id = up.user_id
where up.apply_id = #{id} and  u.deleted= 0  and system_role = 1 and u.status = 1  and up.deleted = 0

  and u.user_name like concat('%',#{userName},'%')


  and  u.department_id in

    #{id}



  and up.create_user = #{dataFilterUserId}


  and up.create_department_id in

    #{item}
